import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import React, {useEffect, useRef, useState} from "react";
import "./ChatWidget.scss";
import {CHAT_LIMITS, CHAT_WORKER_URL} from "../../chatConfig";
import {loadKnowledge} from "../../chat/knowledge";
import {
  buildChatRequest,
  cleanMessages,
  readSession,
  saveSession
} from "../../chat/conversation";

const welcome = {
  role: "assistant",
  kind: "greeting",
  content:
    "Olá! Posso ajudar com os projetos, habilidades e experiência do Lucas. O que você gostaria de saber?"
};

function initialMessages() {
  try {
    const saved = readSession(window.sessionStorage);
    return saved.length ? saved : [welcome];
  } catch {
    return [welcome];
  }
}

export default function ChatWidget() {
  const [isOpen, setIsOpen] = useState(false);
  const [isSending, setIsSending] = useState(false);
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState(initialMessages);
  const messagesEndRef = useRef(null);
  const sendLock = useRef(false);

  useEffect(() => {
    try {
      saveSession(window.sessionStorage, messages);
    } catch {
      /* Storage may be disabled. */
    }
  }, [messages]);

  useEffect(() => {
    const container = messagesEndRef.current;
    if (container) container.scrollTop = container.scrollHeight;
  }, [messages, isOpen]);

  const handleSubmit = async event => {
    event.preventDefault();
    const question = input.trim();
    if (
      !question ||
      sendLock.current ||
      question.length > CHAT_LIMITS.questionChars
    )
      return;
    sendLock.current = true;
    setIsSending(true);
    setInput("");
    const updatedHistory = cleanMessages([
      ...messages,
      {role: "user", content: question}
    ]);
    setMessages(updatedHistory);
    let timeout;

    try {
      const chunks = await loadKnowledge();
      const request = buildChatRequest(chunks, question, messages);
      const controller = new AbortController();
      timeout = setTimeout(() => controller.abort(), 30000);
      const response = await fetch(CHAT_WORKER_URL, {
        method: "POST",
        signal: controller.signal,
        headers: {"Content-Type": "application/json"},
        body: JSON.stringify({messages: request.messages})
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();
      if (!data || typeof data.reply !== "string" || !data.reply.trim())
        throw new Error("Resposta vazia.");
      setMessages(
        cleanMessages([
          ...updatedHistory,
          {role: "assistant", content: data.reply}
        ])
      );
    } catch (error) {
      const content =
        error.name === "AbortError"
          ? "A resposta demorou mais que o esperado. Tente novamente."
          : "Não foi possível consultar o currículo agora. Tente novamente ou entre em contato pelos links do portfólio.";
      setMessages(
        cleanMessages([
          ...updatedHistory,
          {role: "assistant", kind: "error", content}
        ])
      );
    } finally {
      clearTimeout(timeout);
      sendLock.current = false;
      setIsSending(false);
    }
  };

  return (
    <>
      <button
        type="button"
        className="lh-chat-toggle pulse-chat"
        onClick={() => setIsOpen(previous => !previous)}
        aria-label={
          isOpen
            ? "Fechar assistente do portfólio"
            : "Abrir assistente do portfólio"
        }
        aria-expanded={isOpen}
        aria-controls="portfolio-chat"
      >
        Chat
      </button>
      {isOpen && (
        <div
          className="lh-chat"
          id="portfolio-chat"
          role="dialog"
          aria-label="Assistente do portfólio"
        >
          <div className="lh-chat__header">
            <span>Assistente do portfólio</span>
            <button
              type="button"
              className="lh-chat__reset"
              disabled={isSending}
              onClick={() => {
                setMessages([welcome]);
                setInput("");
              }}
            >
              Nova conversa
            </button>
          </div>
          <div
            className="lh-chat__msgs"
            ref={messagesEndRef}
            role="log"
            aria-live="polite"
          >
            {messages.map((message, index) => (
              <div
                key={`${message.role}-${index}`}
                className={`lh-msg ${
                  message.role === "user" ? "lh-msg--user" : "lh-msg--bot"
                }`}
              >
                <ReactMarkdown
                  className="lh-msg__markdown"
                  remarkPlugins={[remarkGfm]}
                >
                  {message.content}
                </ReactMarkdown>
              </div>
            ))}
            {isSending && (
              <div className="lh-msg lh-msg--bot" role="status">
                Consultando…
              </div>
            )}
          </div>
          <form className="lh-chat__form" onSubmit={handleSubmit}>
            <textarea
              className="lh-chat__input"
              aria-label="Pergunta sobre o portfólio"
              placeholder="Pergunte sobre o Lucas…"
              value={input}
              onChange={event => setInput(event.target.value)}
              disabled={isSending}
              maxLength={CHAT_LIMITS.questionChars}
              rows={1}
            />
            <button
              type="submit"
              className="lh-chat__submit"
              disabled={isSending || !input.trim()}
            >
              {isSending ? "…" : "Enviar"}
            </button>
          </form>
        </div>
      )}
    </>
  );
}
