import React, {useState, useEffect, useContext} from "react";
import "./Blog.scss";
import BlogCard from "../../components/blogCard/BlogCard";
import {blogSection} from "../../portfolio";
import {Fade} from "react-reveal";
import StyleContext from "../../contexts/StyleContext";
import config from "../../mediumConfig.json";
import snapshot from "../../data/medium-posts.json";
import {normalizePosts} from "../../mediumPosts";

export default function Blogs() {
  const {isDark} = useContext(StyleContext);
  const useMedium = blogSection.displayMediumBlogs === "true";
  const [posts, setPosts] = useState(() =>
    normalizePosts(
      useMedium && snapshot.username === config.username
        ? snapshot.items
        : blogSection.blogs
    )
  );

  useEffect(() => {
    if (!blogSection.display || !useMedium) return;
    const controller = new AbortController();
    let active = true;
    const timeout = setTimeout(() => controller.abort(), 8000);
    fetch(`${process.env.PUBLIC_URL || ""}/blogs.json`, {
      signal: controller.signal
    })
      .then(response => {
        if (!response.ok) throw new Error("Articles unavailable");
        return response.json();
      })
      .then(data => {
        if (
          !data ||
          data.username !== config.username ||
          !Array.isArray(data.items)
        )
          throw new Error("Invalid articles");
        if (active) setPosts(normalizePosts(data.items));
      })
      .catch(() => {
        // The bundled snapshot remains visible when generated data is unavailable.
      })
      .finally(() => clearTimeout(timeout));
    return () => {
      active = false;
      clearTimeout(timeout);
      controller.abort();
    };
  }, [useMedium]);

  if (!blogSection.display) return null;
  return (
    <Fade bottom duration={1000} distance="20px">
      <section
        className="main medium-section"
        id="blogs"
        aria-labelledby="medium-heading"
      >
        <div className="medium-section-header">
          <div>
            <h1 className="blog-header-text" id="medium-heading">
              {blogSection.title}
            </h1>
            <p
              className={
                isDark ? "dark-mode blog-subtitle" : "subTitle blog-subtitle"
              }
            >
              {blogSection.subtitle}
            </p>
          </div>
          <a
            className="medium-profile-link"
            href={`https://medium.com/@${config.username}`}
            target="_blank"
            rel="noopener noreferrer"
          >
            Todos os artigos no Medium <span aria-hidden="true">↗</span>
          </a>
        </div>
        {posts.length ? (
          <div className="medium-posts-grid">
            {posts.map(post => (
              <BlogCard key={post.url} isDark={isDark} blog={post} />
            ))}
          </div>
        ) : (
          <p className="medium-empty">
            Confira minhas publicações diretamente no perfil do Medium.
          </p>
        )}
      </section>
    </Fade>
  );
}
