import {CHAT_KNOWLEDGE_URL, CHAT_LIMITS} from "../chatConfig";

export const normalize = text =>
  String(text)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/c\+\+/g, "cpp")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();

const STOP_WORDS = new Set(
  normalize(
    "a o as os de da do das dos em no na nos nas um uma e ou que qual quais como para por com sem seu sua seus suas ele ela dele dela esse essa isso este esta sobre me voce voces eu lucas harada the a an of in to for with is are was what which how his he she it this that about tell can does and"
  ).split(" ")
);
const ALIASES = [
  [/^(certific|credential|credencia|certificate)/, "certificacao"],
  [/^(experien|employment|internship|trabalho|emprego)/, "experiencia"],
  [/^(projet|project)/, "projeto"],
  [/^(forma[cç]|educa|education|degree|university|faculdade)/, "formacao"],
  [/^(idioma|language)/, "idioma"],
  [/^(integra|integration)/, "integracao"],
  [/^(orquestra|orchestra)/, "orquestracao"],
  [/^(habilidade|competen|skill)/, "habilidade"],
  [/^(resultado|result|metric|impact)/, "resultado"],
  [/^(contato|contact)/, "contato"]
];

export function tokenize(text) {
  return normalize(text)
    .split(" ")
    .filter(word => word.length > 1 && !STOP_WORDS.has(word))
    .map(word => {
      const alias = ALIASES.find(([pattern]) => pattern.test(word));
      return alias ? alias[1] : word;
    });
}

export function parseKnowledge(text) {
  return text
    .replace(/\r/g, "")
    .split(/^## /m)
    .slice(1)
    .map(section => {
      const [header, ...lines] = section.trim().split("\n");
      const [id, title] = header.split(" | ");
      const tags = lines.filter(line => line.startsWith("Busca:")).join(" ");
      const content = lines
        .filter(line => !line.startsWith("Busca:"))
        .join("\n")
        .trim();
      return {
        id,
        title,
        content,
        terms: tokenize(`${title} ${tags} ${content}`),
        keywords: new Set(tokenize(`${title} ${tags}`))
      };
    })
    .filter(chunk => chunk.id && chunk.title && chunk.content);
}

let pendingKnowledge;
export function loadKnowledge() {
  if (!pendingKnowledge) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 8000);
    pendingKnowledge = fetch(CHAT_KNOWLEDGE_URL, {
      cache: "no-cache",
      signal: controller.signal
    })
      .then(response => {
        if (!response.ok)
          throw new Error("Não foi possível carregar o currículo.");
        return response.text();
      })
      .then(text => {
        const chunks = parseKnowledge(text);
        if (!chunks.some(chunk => chunk.id === "perfil"))
          throw new Error("Base do currículo inválida.");
        return chunks;
      })
      .catch(error => {
        pendingKnowledge = null;
        throw error;
      })
      .finally(() => clearTimeout(timeout));
  }
  return pendingKnowledge;
}

function scoreChunks(chunks, weightedTerms) {
  return chunks
    .map(chunk => {
      let score = 0;
      weightedTerms.forEach((weight, term) => {
        const frequency = chunk.terms.filter(value => value === term).length;
        if (!frequency) return;
        const documents = chunks.filter(item =>
          item.terms.includes(term)
        ).length;
        const idf = Math.log(
          1 + (chunks.length - documents + 0.5) / (documents + 0.5)
        );
        score +=
          weight *
          idf *
          (frequency / (frequency + 1.2)) *
          (chunk.keywords.has(term) ? 2 : 1);
      });
      return {...chunk, score};
    })
    .sort((a, b) => b.score - a.score);
}

export function retrieveKnowledge(
  chunks,
  question,
  history = [],
  limits = CHAT_LIMITS
) {
  const terms = new Map(tokenize(question).map(term => [term, 1]));
  // Only inherit topic for short follow-ups, never for an explicit topic switch.
  const explicitTopic =
    /professor|vgc|vocal|copilot|co pilot|finstatement|casa|certific|contato|contact|formacao|idioma|language|cloud|python|java|salesforce|sap/.test(
      normalize(question)
    );
  const followUp =
    /\b(esse|essa|nesse|nessa|neste|nesta|ele|ela|dele|dela|isso|it|its|that|this|resultados|results|usou|utilizou|used)\b|^(e |and |mais|more|como assim|por que)/.test(
      normalize(question)
    );
  if (!explicitTopic && followUp && tokenize(question).length <= 6) {
    history
      .filter(message => !message.kind)
      .slice(-4)
      .forEach((message, index) => {
        const weight = message.role === "user" ? 0.45 : 0.15;
        tokenize(message.content).forEach(term =>
          terms.set(term, (terms.get(term) || 0) + (weight * (index + 1)) / 4)
        );
      });
  }
  if (!terms.size) terms.set("perfil", 1);
  const ranked = scoreChunks(chunks, terms);
  const selected = [];
  let chars = 0;
  for (const chunk of ranked) {
    if (chunk.score <= 0 || selected.length >= limits.chunks) break;
    const cost =
      chunk.title.length + chunk.content.length + chunk.id.length + 8;
    // Preserve whole evidence chunks; don't cut metrics or dates mid-sentence.
    if (chars + cost > limits.knowledgeChars) continue;
    selected.push(chunk);
    chars += cost;
  }
  return selected;
}
