import React from "react";
import "./BlogCard.scss";

export default function BlogCard({blog, isDark}) {
  const date = blog.date
    ? new Intl.DateTimeFormat("pt-BR", {
        day: "numeric",
        month: "short",
        year: "numeric",
        timeZone: "UTC"
      }).format(new Date(blog.date))
    : null;

  return (
    <article
      className={isDark ? "medium-post medium-post-dark" : "medium-post"}
    >
      <a
        className="medium-post-link"
        href={blog.url}
        target="_blank"
        rel="noopener noreferrer"
      >
        <span className="medium-post-source">Medium</span>
        <h2 className="medium-post-title">{blog.title}</h2>
        {blog.description && (
          <p className="medium-post-description">{blog.description}</p>
        )}
        <div className="medium-post-footer">
          {date && <time dateTime={blog.date}>{date}</time>}
          <span>
            Ler artigo <span aria-hidden="true">↗</span>
          </span>
        </div>
      </a>
    </article>
  );
}
