import React from "react";
import "./Progress.scss";
import {illustration, techStack} from "../../portfolio";
import {Fade} from "react-reveal";
import Build from "../../assets/lottie/build";
import DisplayLottie from "../../components/displayLottie/DisplayLottie";

export default function StackProgress({embedded = false}) {
  if (techStack.viewSkillBars) {
    return (
      <Fade bottom duration={1000} distance="20px">
        <div
          className={embedded ? "skills-progress-embedded" : "skills-container"}
        >
          <div className="skills-bar">
            {embedded ? (
              <h3 className="skill-areas-title">Áreas de atuação</h3>
            ) : (
              <h1 className="skills-heading">Áreas de atuação</h1>
            )}
            {techStack.experience.map((exp, i) => {
              return (
                <div key={i} className="skill">
                  <div className="skill-area-label">
                    <h4 className="skill-area-name">{exp.Stack}</h4>
                    <span aria-hidden="true">{exp.proficiency}%</span>
                  </div>
                  <p className="skill-area-description">{exp.description}</p>
                  <div
                    className="skill-area-bar"
                    role="meter"
                    aria-label={exp.Stack}
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-valuenow={exp.proficiency}
                  >
                    <span style={{width: `${exp.proficiency}%`}} />
                  </div>
                </div>
              );
            })}
          </div>

          {!embedded && (
            <div className="skills-image">
              {illustration.animated ? (
                <DisplayLottie animationData={Build} />
              ) : (
                <img
                  alt="Skills"
                  src={require("../../assets/images/skill.svg")}
                />
              )}
            </div>
          )}
        </div>
      </Fade>
    );
  }
  return null;
}
