const config = require("./mediumConfig.json");

function cleanText(value) {
  return typeof value === "string"
    ? value
        .replace(/<[^>]*>/g, " ")
        .replace(/\s+/g, " ")
        .trim()
    : "";
}

function normalizePosts(items, limit = config.maxPosts) {
  if (!Array.isArray(items)) return [];
  const seen = new Set();
  return items
    .reduce((result, item) => {
      if (!item || typeof item !== "object") return result;
      const title = cleanText(item.title);
      let url;
      try {
        url = new URL(item.url || item.link);
        if (url.protocol !== "https:" || url.username || url.password)
          return result;
        url.search = "";
        url.hash = "";
      } catch {
        return result;
      }
      if (!title || seen.has(url.href)) return result;
      seen.add(url.href);
      const time = Date.parse(item.date || item.isoDate || item.pubDate);
      const description = cleanText(item.description);
      result.push({
        title,
        url: url.href,
        description:
          description.length > config.excerptChars
            ? `${description.slice(0, config.excerptChars - 1).trim()}…`
            : description,
        date: Number.isFinite(time) ? new Date(time).toISOString() : null
      });
      return result;
    }, [])
    .sort((a, b) => (Date.parse(b.date) || 0) - (Date.parse(a.date) || 0))
    .slice(0, limit);
}

module.exports = {normalizePosts};
