import React, {useState, useEffect} from "react";
import {openSource, contactInfo, greeting} from "../../portfolio";
import Contact from "../contact/Contact";
import GithubProfileCard from "../../components/githubProfileCard/GithubProfileCard";

export default function Profile() {
  const [profile, setProfile] = useState(null);
  const showProfile = openSource.showGithubProfile === "true";

  useEffect(() => {
    if (!showProfile) return;
    let active = true;
    fetch(`${process.env.PUBLIC_URL}/profile.json`)
      .then(response => {
        if (!response.ok) throw new Error("Profile unavailable");
        return response.json();
      })
      .then(response => {
        const user = response && response.data && response.data.user;
        if (active && user && typeof user === "object") setProfile(user);
      })
      .catch(() => {
        // Keep the local profile when generated GitHub data is unavailable.
      });
    return () => {
      active = false;
    };
  }, [showProfile]);

  if (!showProfile) return <Contact />;

  return (
    <GithubProfileCard
      prof={{
        name: (profile && profile.name) || greeting.username,
        bio: (profile && profile.bio) || contactInfo.headline,
        location: (profile && profile.location) || contactInfo.location,
        avatarUrl: (profile && profile.avatarUrl) || contactInfo.profileImage
      }}
    />
  );
}
